pub fn boot_action(pending_marker: bool, previous_kept: bool) -> u8 {
    if !(pending_marker) {
        return BOOT_RUN;
    }
    if previous_kept {
        return BOOT_ROLLBACK;
    }
    return BOOT_BROKEN;
}

pub fn confirm_due(uptime_s: u64) -> bool {
    return (uptime_s >= CONFIRM_AFTER_S);
}

pub fn previous_after(swapped: bool, rolled_back: bool, previous_kept: bool) -> bool {
    if rolled_back {
        return false;
    }
    if swapped {
        return true;
    }
    return previous_kept;
}

pub fn rejected_after(boot: u8, running: u64, rejected: u64) -> u64 {
    if (boot == BOOT_ROLLBACK) {
        return running;
    }
    return rejected;
}

